def price_to_offer(apps, schema_editor):
    """Turn each artwork's old single price into an 'original' way to buy."""
    ArtworkPage = apps.get_model("artworks", "ArtworkPage")
    Offer = apps.get_model("artworks", "Offer")
    for page in ArtworkPage.objects.exclude(price__isnull=True):
        Offer.objects.create(
            artwork=page,
            kind="original",
            price=page.price,
            shipping_class="parcel",
            is_active=True,
        )


def offer_to_price(apps, schema_editor):
    ArtworkPage = apps.get_model("artworks", "ArtworkPage")
    Offer = apps.get_model("artworks", "Offer")
    for offer in Offer.objects.filter(kind="original"):
        ArtworkPage.objects.filter(pk=offer.artwork_id).update(
            price=offer.price, show_price=True
        )


